trans-unit.source:
{% if group.type == 0 or group.type == 1 %}
        Language: {{notification.language}}
        <0><0>
        {% endif %}
        <1><2>String</2></1>

trans-unit.target:
{% if group.type == 0 or group.type == 1 %}
        Språk: {{notification.language}}
        <0><0>
        {% endif %}
        <1><2>Sträng</2></1>

{count, plural,
one {<span class="font-semibold px-2 py-1 bg-gray-100 dark:bg-gray-800 rounded-md">#</span> skärmbild}
other {<span class="font-semibold px-2 py-1 bg-gray-100 dark:bg-gray-800 rounded-md">#</span> skärmbilder}
}
